<?php
if (!defined('ABSPATH')) exit;
/** Explicit manual reconciliation; no deletion, no guessed chapters, fail closed. */
final class MBI_Root_Reconcile {
 private const OPT='mbi_root_reconcile';
 private MBI_Importer $importer; private MBI_DB $db;
 public function __construct(MBI_Importer $i,MBI_DB $d){$this->importer=$i;$this->db=$d;add_action('admin_menu',[$this,'menu']);add_action('admin_enqueue_scripts',[$this,'assets']);add_action('admin_post_mbi_root_reconcile',[$this,'ajax']);add_filter('wp_insert_post_data',[$this,'publication'],100,2);}
 public function menu():void{add_submenu_page('edit.php?post_type=mbi_manga','Obedecer à origem','Obedecer à origem','manage_options','mbi-root-reconcile',[$this,'render']);}
 public function assets(string $hook):void{if(!str_contains($hook,'mbi-root-reconcile'))return;wp_enqueue_script('mbi-root-reconcile',MBI_URL.'assets/root-reconcile.js',[],MBI_VERSION,true);wp_localize_script('mbi-root-reconcile','MBIRoot',['url'=>admin_url('admin-post.php'),'nonce'=>wp_create_nonce('mbi_root_reconcile')]);}
 public function render():void{if(!current_user_can('manage_options'))return;?><div class="wrap" id="mbi-root-reconcile"><h1>Obedecer à origem — capítulos (v<?php echo esc_html(MBI_VERSION); ?>)</h1><p>Confere duas vezes a lista completa da origem, com intervalo mínimo de 30 segundos. Só capítulos ausentes nas duas consultas são colocados em rascunho. Não apaga dados nem altera as obras. Lista incompleta, erro ou bloqueio: preserva e passa à próxima obra.</p><p><button class="button button-primary" data-command="start">Conferir e reconciliar todas as obras publicadas</button> <button class="button" data-command="retry">Repetir somente obras não conferidas</button> <button class="button" data-command="resume">Continuar</button> <button class="button" data-command="stop">Parar esta conferência</button> <button class="button" data-command="stop_others">Parar outros reparos e liberar esta tela</button></p><progress max="100" value="0" style="width:100%"></progress><p role="status"></p><table class="widefat striped"><thead><tr><th>Mangá</th><th>Resultado</th></tr></thead><tbody></tbody></table><p>Mantenha esta tela aberta. Pause importações e reparos antes de iniciar. Capítulos retirados conservam seus dados e podem voltar se reaparecerem na lista confirmada da origem.</p></div><?php }
 private function state():array{if(function_exists('wp_cache_delete'))wp_cache_delete(self::OPT,'options');return (array)get_option(self::OPT,[]);}
 private function valid(string $run):bool{$s=$this->state();return !empty($s['active'])&&($s['id']??'')===$run;}
 private function idle():void{$c=$this->db->counts();if(!empty($c['processing'])||(!$this->importer->is_paused()&&(!empty($c['pending'])||$this->importer->is_serial_active())))throw new RuntimeException('Pause o importador e aguarde o trabalho atual terminar.');foreach(self::repairs() as $key=>$label)if(!empty(get_option($key,[])['active']))throw new RuntimeException('Bloqueado por: '.$label.'. Clique em “Parar outros reparos e liberar esta tela”.');}
 private static function repairs():array{return ['mbi_media_repair'=>'Reparar imagens','mbi_media_daily'=>'Reparo rápido / diário','mbi_source_audit'=>'Origens indisponíveis','mbi_cover_refresh'=>'Recuperar capas'];}
 private function failed_ids(array $s):array{$ids=(array)($s['failed_ids']??[]);foreach((array)($s['rows']??[]) as $id=>$row)if(str_starts_with((string)($row['result']??''),'Preservado / revisar:'))$ids[(int)$id]=true;return array_keys($ids);}
 private function stop_others():array{$names=[];foreach(self::repairs() as $key=>$label){$other=(array)get_option($key,[]);if(empty($other['active']))continue;$other['active']=false;$other['id']=wp_generate_uuid4();$other['paused']=false;$other['message']='Parado manualmente na tela Obedecer à origem; dados preservados.';if($key==='mbi_media_repair')$other['stopped']=true;if($key==='mbi_cover_refresh')$other['stage']='stopped';unset($other['browser']);update_option($key,$other,false);$names[]=$label;}$cleared=wp_clear_scheduled_hook('mbi_media_daily_continue');delete_option('mbi_media_daily_deferred');$s=$this->state();$s['message']=$names?'Parados: '.implode(', ',$names).'. Agora clique em Repetir somente obras não conferidas.':'Nenhum outro reparo ativo. Escolha a conferência que deseja executar.';update_option(self::OPT,$s,false);$this->db->log('info','Reparos interrompidos por comando manual; catálogo preservado.',['processes'=>$names]);return $s;}
 public function ajax():void{if(!current_user_can('manage_options')){wp_send_json_error(['message'=>'Acesso negado'],403);return;}check_ajax_referer('mbi_root_reconcile','nonce');try{$cmd=sanitize_key($_POST['command']??'status');$s=$this->state();if($cmd==='start'){$this->idle();if(!empty($s['active']))throw new RuntimeException('Pare a execução atual primeiro.');$ids=get_posts(['post_type'=>'mbi_manga','post_status'=>'publish','fields'=>'ids','posts_per_page'=>-1,'orderby'=>'ID','order'=>'ASC']);$s=['id'=>wp_generate_uuid4(),'active'=>!empty($ids),'ids'=>$ids,'index'=>0,'pass'=>1,'total'=>count($ids),'done'=>0,'rows'=>[],'snapshots'=>[],'current'=>'Iniciando'];update_option(self::OPT,$s,false);}elseif($cmd==='stop_others'){$s=$this->stop_others();}elseif($cmd==='retry'){$this->idle();if(!empty($s['active']))throw new RuntimeException('Pare a execução atual primeiro.');$ids=$this->failed_ids($s);if(!$ids)throw new RuntimeException('Não existem conferências com falha para repetir.');$s=['id'=>wp_generate_uuid4(),'active'=>true,'ids'=>$ids,'index'=>0,'pass'=>1,'total'=>count($ids),'done'=>0,'rows'=>[],'snapshots'=>[],'failed_ids'=>[],'current'=>'Repetindo somente falhas'];update_option(self::OPT,$s,false);}elseif($cmd==='stop'){$s['active']=false;$s['id']=wp_generate_uuid4();update_option(self::OPT,$s,false);}elseif($cmd==='resume'){$this->idle();if(empty($s['ids']))throw new RuntimeException('Inicie uma nova conferência.');$s['active']=true;$s['id']=wp_generate_uuid4();update_option(self::OPT,$s,false);}elseif($cmd==='tick'){$s=$this->tick(sanitize_text_field($_POST['run_id']??''));}unset($s['ids'],$s['snapshots']);wp_send_json_success($s);}catch(Throwable $e){wp_send_json_error(['message'=>$e->getMessage()],400);}}
 private function fetch(string $url):array{$parts=wp_parse_url($url);$hosts=array_map('trim',preg_split('/[\r\n,]+/',(string)$this->importer->settings()['allowed_hosts']));if(($parts['scheme']??'')!=='https'||!in_array($parts['host']??'',$hosts,true)||isset($parts['user'])||isset($parts['pass'])||(isset($parts['port'])&&(int)$parts['port']!==443))throw new RuntimeException('Origem não autorizada.');$r=wp_safe_remote_get($url,['timeout'=>8,'redirection'=>0,'limit_response_size'=>8388608,'headers'=>['Cache-Control'=>'no-cache','User-Agent'=>'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/131.0.0.0 Safari/537.36']]);if(is_wp_error($r))throw new RuntimeException('Falha de acesso: '.$r->get_error_message().'; capítulos preservados.');if(wp_remote_retrieve_response_code($r)!==200)throw new RuntimeException('HTTP '.wp_remote_retrieve_response_code($r).' na origem; capítulos preservados.');$html=wp_remote_retrieve_body($r);if(strlen($html)>=8388608||!str_contains(strtolower($html),'</html>'))throw new RuntimeException('HTML incompleto; preservado.');$p=new MBI_Parser();$p->load($html,$url);$data=$p->parse_manga($url);if(empty($data['title']))throw new RuntimeException('Página da obra não validada; preservada.');return $p->authoritative_chapter_urls();}
 public static function key(string $url):string{return rtrim($url,'/').'/';}
 public function tick( string $run ): array {
		if ( ! MBI_Resource_Guard::begin( 'conferência da origem', true ) ) { return $this->state(); }
		try { return $this->tick_bounded( $run ); } finally { MBI_Resource_Guard::end(); }
	}

	private function tick_bounded( string $run ): array {if(!$this->valid($run))return $this->state();$token=wp_generate_uuid4();if(!add_option('mbi_root_reconcile_lock',['token'=>$token,'until'=>time()+45],'',false)){$l=get_option('mbi_root_reconcile_lock',[]);if(($l['until']??0)<time())delete_option('mbi_root_reconcile_lock');return $this->state();}try{$s=$this->state();$id=(int)($s['ids'][$s['index']]??0);if(!$id){$s['active']=false;update_option(self::OPT,$s,false);return $s;}$source=(string)get_post_meta($id,'_mbi_source_url',true);$title=get_the_title($id);$s['current']=$title;update_option(self::OPT,$s,false);try{if(get_post_status($id)!=='publish')throw new RuntimeException('Obra não publicada; preservada.');$first=$s['snapshots'][$id]??[];if($s['pass']===2&&($first['at']??0)>time()-30)return $s;$urls=$this->fetch($source);if(!$this->valid($run))return $this->state();if($source!==(string)get_post_meta($id,'_mbi_source_url',true))throw new RuntimeException('URL mudou; preservada.');if($s['pass']===1){$s['snapshots'][$id]=['url'=>$source,'urls'=>$urls,'at'=>time()];$result=count($urls).' capítulos na origem — aguardando confirmação';}else{if(($first['url']??'')!==$source||($first['urls']??[])!==$urls)throw new RuntimeException('Lista mudou entre consultas; preservada.');$set=array_fill_keys($urls,true);$removed=0;$restored=0;$chapters=get_posts(['post_type'=>'mbi_chapter','post_parent'=>$id,'post_status'=>['publish','draft'],'posts_per_page'=>-1,'fields'=>'ids']);foreach($chapters as $cid){if(!$this->valid($run))return $this->state();$u=(string)get_post_meta($cid,'_mbi_source_url',true);if(!$u)continue;$backup=get_post_meta($cid,'_mbi_root_absent',true);if(!isset($set[self::key($u)])&&get_post_status($cid)==='publish'){update_post_meta($cid,'_mbi_root_absent',['status'=>'publish','source'=>$u,'root'=>$source,'at'=>time()]);if(!get_post_meta($cid,'_mbi_root_absent',true))throw new RuntimeException('Backup não gravado; preservado.');$r=wp_update_post(['ID'=>$cid,'post_status'=>'draft'],true);if(is_wp_error($r)||get_post_status($cid)!=='draft')throw new RuntimeException('Falha ao retirar capítulo; revisar registro.');$removed++;$this->db->log('warning','Capítulo ausente na lista completa confirmada da origem; colocado em rascunho, dados preservados.',['post_id'=>$cid,'url'=>$u,'manga_id'=>$id]);}elseif(isset($set[self::key($u)])&&$backup&&get_post_status($cid)==='draft'&&($backup['source']??'')===$u&&($backup['root']??'')===$source){delete_post_meta($cid,'_mbi_root_absent');$r=wp_update_post(['ID'=>$cid,'post_status'=>'publish'],true);if(is_wp_error($r)||get_post_status($cid)!=='publish'){update_post_meta($cid,'_mbi_root_absent',$backup);throw new RuntimeException('Falha ao restaurar capítulo.');}$restored++;}}if(!$this->valid($run))return $this->state();update_post_meta($id,'_mbi_source_chapter_urls',$urls);update_post_meta($id,'_mbi_expected_chapters',count($urls));unset($s['failed_ids'][$id]);$result=count($urls)." na origem; $removed retirados; $restored restaurados. Novos capítulos continuam com publicação manual.";do_action('litespeed_purge_all');if(function_exists('wpo_cache_flush'))wpo_cache_flush();}}catch(Throwable $e){$s['failed_ids'][$id]=true;$result='Preservado / revisar: '.$e->getMessage();unset($s['snapshots'][$id]);$this->db->log('warning','Conferência de capítulos preservou catálogo.',['manga_id'=>$id,'url'=>$source,'error'=>$e->getMessage()]);}if(!$this->valid($run))return $this->state();$s['rows'][$id]=['title'=>$title,'result'=>$result];$s['index']++;$s['done']=$s['index'];if($s['index']>=count($s['ids'])){if($s['pass']===1){$s['ids']=array_keys($s['snapshots']);$s['index']=0;$s['done']=0;$s['total']=count($s['ids']);$s['pass']=2;}else $s['active']=false;if(!$s['ids'])$s['active']=false;}update_option(self::OPT,$s,false);return $s;}finally{if((get_option('mbi_root_reconcile_lock',[])['token']??'')===$token)delete_option('mbi_root_reconcile_lock');}}
 public function publication(array $data,array $post):array{if(($data['post_type']??'')==='mbi_chapter'&&($data['post_status']??'')==='publish'&&!empty($post['ID'])&&get_post_meta((int)$post['ID'],'_mbi_root_absent',true))$data['post_status']='draft';return $data;}
}
